style.css:
@-moz-document domain("rumble.com") {
/* 01. Twitch v1.0.8 canvas and Rumble's native component colors */
html, html.dark, html.light {
  color-scheme: dark !important;
  --font-base: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  --background: #07180e !important;
  --background-highlight: #124329 !important;
  --subtle-highlight: #10351f !important;
  --surface: #0b2b19 !important;
  --color-bg-default: #07180e !important;
  --color-bg-default-0: rgba(7,24,14,0) !important;
  --color-bg-featured: #07180e !important;
  --color-bg-featured-0: rgba(7,24,14,0) !important;
  --color-bg-main: #07180e !important;
  --color-txt-default: #d9ffe6 !important;
  --primary: #d9ffe6 !important;
  --primary-variant: #9ee5b6 !important;
  --secondary-variant: #9ee5b6 !important;
  --title-color: #d9ffe6 !important;
  --on-secondary: #17432b !important;
  --link-green: #68ffa3 !important;
  --brand-400: #38ff87 !important;
  --brand-500: #00e85c !important;
  --brand-500-rgb: 0 232 92 !important;
  --brand-600: #00c84c !important;
  --rumble-logo-color: #00ff66 !important;
  --color-separator: rgba(32,243,107,.18) !important;
  --color-separator-highlight: rgba(32,243,107,.26) !important;
  --channel-border: rgba(32,243,107,.24) !important;
  --channel-border-dark: rgba(32,243,107,.24) !important;
  --channel-border-light: rgba(32,243,107,.24) !important;
  --menu-border-color: rgba(28,240,102,.36) !important;
  --menu-icon-color: #7fffac !important;
  --menu-item-hover: rgba(17,117,53,.40) !important;
  background-color: #0a0a0a !important;
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}
body, button, input, select, textarea, [contenteditable="true"] {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", Consolas, "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}
body { color: #d9ffe6 !important; }
body, body > main, .homepage-featured, .homepage-featured > .constrained,
.homepage-section, .section-content, .channel-listing__container,
.main-and-sidebar, .media-container, .media-page-chat-body-container,
.media-page-chat-body-content {
  background-color: transparent !important;
}
a { text-decoration-color: rgba(69,255,137,.65) !important; }
a:hover { text-decoration-color: #b5ffd1 !important; }
::selection { background-color: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }

/* 02. Header, search, and left navigation */
header.header {
  background-color: rgba(1,20,9,.70) !important;
  border-color: rgba(24,241,106,.22) !important;
  box-shadow: inset 0 -1px 0 rgba(24,241,106,.22) !important;
  backdrop-filter: blur(11px) saturate(125%) !important;
}
.header-div { background-color: transparent !important; }
.header-div > a[href="/"] > svg,
.header-div > a[href="/"] > img {
  color: #00ff66 !important;
  filter: drop-shadow(0 0 4px rgba(0,255,102,.85)) drop-shadow(0 0 12px rgba(0,255,102,.35)) !important;
}
.header-div > a[href="/"]:hover > svg,
.header-div > a[href="/"]:hover > img {
  filter: drop-shadow(0 0 5px rgba(0,255,102,.95)) drop-shadow(0 0 14px rgba(0,255,102,.55)) !important;
}
.header-search-container {
  background-color: rgba(4,43,20,.95) !important;
  border-color: rgba(28,240,102,.36) !important;
}
.header-search-container .header-search-field { background-color: transparent !important; }
.header-search-container:focus-within {
  border-color: #00ff66 !important;
  box-shadow: 0 0 10px rgba(0,255,102,.22) !important;
}
.header-search-submit, .main-menu-toggle { color: #7fffac !important; }
.header-search-submit:hover, .main-menu-toggle:hover {
  color: #effff4 !important;
  background-color: rgba(12,91,39,.56) !important;
}
nav.navs { background-color: transparent !important; }
#main-menu {
  background-color: rgba(2,24,13,.28) !important;
  background-image: linear-gradient(to left,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.32) 42%, rgba(1,19,11,.52) 100%) !important;
  border-color: rgba(67,255,134,.36) !important;
  box-shadow: inset -2px 0 0 rgba(67,255,134,.90),
    inset -10px 0 18px -11px rgba(0,255,102,.75),
    5px 0 22px -8px rgba(0,255,102,.60) !important;
}
#main-menu .main-menu-item, #main-menu .main-menu-item-channel {
  color: #c0ffd5 !important;
}
#main-menu .main-menu-heading { color: #9ee5b6 !important; }
#main-menu .main-menu-item:hover, #main-menu .main-menu-item-channel:hover,
#main-menu .main-menu-item.active, #main-menu a[aria-current="page"] {
  background-color: rgba(17,117,53,.40) !important;
  color: #effff4 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76), 0 0 10px rgba(0,255,102,.09) !important;
}
#main-menu hr, #main-menu .main-menu-divider, .category-header .bottom-border, .channel-listing__container hr {
  border-color: rgba(32,243,107,.22) !important;
}

/* 03. Shelves, browse, search and thumbnails */
.category-header, .channel-header--content, .video-list-header, .search-header {
  background-color: rgba(1,20,9,.58) !important;
  border-color: rgba(24,241,106,.22) !important;
  box-shadow: inset 0 -1px 0 rgba(24,241,106,.22) !important;
}
.homepage-section h2, .category-header h1, .channel-header--title h1,
.video-header-container h1, #video-comments h3, .video-item--title,
.category__title {
  color: #d9ffe6 !important;
}
.video-item--meta, .category__views, .media-heading-num-followers,
.media-description-time-views-container {
  color: #9ee5b6 !important;
}
rum-video-thumbnail-footer, .video-item {
  background-color: rgba(1,22,10,.56) !important;
  border-radius: 8px !important;
}
rum-video-thumbnail:hover .rum-video-thumbnail__image,
rum-video-thumbnail:focus-within .rum-video-thumbnail__image,
.video-item--a:hover .video-item--img, .video-item--a:focus-visible .video-item--img,
.category__link:hover .category__image, .category__link:focus-visible .category__image {
  box-shadow: 0 0 0 1px rgba(67,255,134,.86), 0 0 13px rgba(0,255,102,.45) !important;
}
rum-video-thumbnail-footer a:hover, .video-item--a:hover .video-item--title,
.category__link:hover .category__title, .media-by--a:hover .media-heading-name,
.content a:hover {
  color: #b5ffd1 !important;
}

/* 04. Watch pages and creator channel listings */
#videoPlayer, .media-theater-container {
  background-color: transparent !important;
}
.media-container > .media-info {
  position: relative !important;
  background-color: transparent !important;
  background-image: linear-gradient(to bottom,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.32) 48%, rgba(1,19,11,.16) 100%) !important;
  box-shadow: inset 0 2px 0 rgba(67,255,134,.90),
    inset 0 10px 18px -11px rgba(0,255,102,.75),
    0 -5px 22px -8px rgba(0,255,102,.60) !important;
}
.media-container > .media-info::after {
  content: "" !important;
  position: absolute !important;
  top: 100% !important;
  right: 0 !important;
  left: 0 !important;
  height: 160px !important;
  pointer-events: none !important;
  background-image: linear-gradient(to bottom,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.24) 45%, rgba(1,19,11,0) 100%) !important;
  box-shadow: inset 0 2px 0 rgba(67,255,134,.90),
    inset 0 10px 18px -11px rgba(0,255,102,.75) !important;
}
.media-page-chat-body-container { position: relative !important; }
.media-description-section, .media-page-comments-container {
  background-color: rgba(1,22,10,.45) !important;
  border-color: rgba(32,243,107,.24) !important;
}
.media-description-section a, #video-comments .content a {
  color: #68ffa3 !important;
}
.media-description-tags-container a, .video-category-tag {
  background-color: rgba(4,54,27,.68) !important;
  color: #9ee5b6 !important;
}
.media-description-tags-container a:hover, .video-category-tag:hover {
  background-color: rgba(12,91,39,.66) !important;
  color: #d9ffe6 !important;
}
.channel-header--container { background-color: transparent !important; }
.channel-listing__container::before {
  content: "" !important;
  display: block !important;
  height: 2px !important;
  margin: 0 0 14px !important;
  background-color: rgba(67,255,134,.90) !important;
  box-shadow: 0 0 8px rgba(0,255,102,.75), 0 0 18px rgba(0,255,102,.35) !important;
  pointer-events: none !important;
}

/* 05. Live chat, including theater and drawer layouts */
section.chat { background-color: transparent !important; }
.chat--container {
  background-color: rgba(2,24,13,.28) !important;
  background-image: linear-gradient(to right,
    rgba(13,92,47,.48) 0%, rgba(4,47,25,.32) 42%, rgba(1,19,11,.52) 100%) !important;
  border-color: rgba(28,240,102,.36) !important;
  border-left-color: rgba(67,255,134,.90) !important;
  box-shadow: inset 2px 0 0 rgba(67,255,134,.90),
    inset 10px 0 18px -11px rgba(0,255,102,.75),
    -5px 0 22px -8px rgba(0,255,102,.60) !important;
}
.media-page-mobile-drawer-content {
  background-color: #07180e !important;
  border-color: rgba(28,240,102,.36) !important;
}
.chat--header, .chat--signin-container {
  background-color: rgba(1,20,9,.58) !important;
  border-color: rgba(24,241,106,.22) !important;
  box-shadow: inset 0 -1px 0 rgba(24,241,106,.22) !important;
}
.chat--header-title, .chat--height, #chat-history-list {
  color: #d9ffe6 !important;
}
.chat--height, #chat-history-list { background-color: transparent !important; }
#chat-history-list > li:hover { background-color: rgba(12,91,39,.25) !important; }
.chat--sign-in {
  background-color: #00e85c !important;
  border-color: #00e85c !important;
  color: #001b09 !important;
}
.chat--sign-in:hover {
  background-color: #38ff87 !important;
  color: #001b09 !important;
}

/* 06. Buttons, inputs, menus and scrollbars */
.btn.btn-grey, .round-button, .rumbles-vote-pill, .chat--header-button,
.media-page-chat-container-toggle-btn {
  background-color: rgba(4,57,26,.88) !important;
  color: #d9ffe6 !important;
  border-color: rgba(28,240,102,.36) !important;
}
.btn.btn-grey:hover, .round-button:hover, .chat--header-button:hover,
.rumbles-vote-pill button:hover, .media-page-chat-container-toggle-btn:hover {
  background-color: rgba(12,91,39,.78) !important;
  color: #effff4 !important;
  border-color: rgba(45,255,118,.50) !important;
}
.btn.btn-green {
  background-color: #00e85c !important;
  border-color: #00e85c !important;
  color: #001b09 !important;
}
.btn.btn-green:hover {
  background-color: #38ff87 !important;
  border-color: #38ff87 !important;
  color: #001b09 !important;
  box-shadow: 0 0 12px rgba(0,255,102,.26) !important;
}
.btn.btn-green.btn-ghost {
  background-color: transparent !important;
  border-color: rgba(28,240,102,.48) !important;
  color: #7fffac !important;
}
.btn.btn-green.btn-ghost:hover {
  background-color: rgba(12,91,39,.78) !important;
  color: #effff4 !important;
}
input[type="search"], input[type="text"], input[type="email"], input[type="password"],
textarea, select, .chat--container [contenteditable="true"] {
  background-color: rgba(4,43,20,.95) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #effff3 !important;
}
input::placeholder, textarea::placeholder { color: #a6efbb !important; }
input[type="checkbox"], input[type="radio"] { accent-color: #00e85c; }
a:focus-visible, button:focus-visible, input:focus-visible, textarea:focus-visible,
select:focus-visible, [role="button"]:focus-visible, [contenteditable="true"]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
.header-search__autocomplete-wrapper,
.js-unified-header-nav__menu-container,
.video-action-sub-menu, #chat-main-menu, .main-menu__live-tooltip,
rum-popout [role="menu"], [role="listbox"], [role="dialog"], dialog {
  background-color: rgba(2,23,11,.97) !important;
  color: #d9ffe6 !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: 0 10px 26px rgba(0,0,0,.55), 0 0 10px rgba(0,255,102,.13) !important;
}
.js-unified-header-nav__menu-container button:hover,
.js-unified-header-nav__menu-container button.is-selected,
.js-unified-header-nav__menu-container a:hover,
.video-action-sub-menu .media-by-actions-sub-menu-button:hover,
#chat-main-menu button:hover, [role="menuitem"]:hover,
[role="option"][aria-selected="true"] {
  background-color: rgba(17,117,53,.40) !important;
  color: #effff4 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76) !important;
}
body > footer, .foot {
  background-color: rgba(1,22,10,.75) !important;
  border-color: rgba(32,243,107,.18) !important;
}
* { scrollbar-color: rgba(29,191,83,.53) rgba(0,18,7,.18); scrollbar-width: thin; }
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background-color: rgba(0,18,7,.18); }
*::-webkit-scrollbar-thumb { background-color: rgba(29,191,83,.53); border-radius: 8px; }
*::-webkit-scrollbar-thumb:hover { background-color: #70b68b; }
}
